# Analyze the demo more carefully
demo_input = [
    [6, 5, 5, 6, 5, 5, 5, 6, 5, 5, 6, 5, 5, 5, 6, 5, 5, 6, 5, 5, 5],
    [3, 5, 4, 4, 5, 8, 3, 3, 5, 4, 4, 5, 8, 3, 3, 5, 4, 4, 5, 8, 3]
]
demo_output = [
    [6, 5, 5, 6, 5, 5, 5],
    [3, 5, 4, 4, 5, 8, 3]
]

print("Demo input:")
for i, row in enumerate(demo_input):
    print(f"Row {i}: len={len(row)}")

print("\nDemo output:")
for i, row in enumerate(demo_output):
    print(f"Row {i}: len={len(row)}")

# Check horizontal period of demo input
def find_smallest_period(row):
    n = len(row)
    for p in range(1, n//2 + 1):
        if all(row[j] == row[j+p] for j in range(n-p)):
            return p
    return None

print("\nHorizontal periods in demo input:")
for i, row in enumerate(demo_input):
    period = find_smallest_period(row)
    print(f"Row {i}: period={period}")

# Check if output is just the first period
print("\nIs output equal to first N columns?")
for n in range(1, 8):
    match = True
    for i, row in enumerate(demo_output):
        if row != demo_input[i][:n]:
            match = False
            break
    if match:
        print(f"Yes! First {n} columns match output")
